import { names } from '../data';

function Table({ range }) {
    // Calculating the time difference of two dates
    const difference_in_time = range[0].endDate - range[0].startDate;
    // Calculating the no. of days between two dates
    const difference_in_days = Math.round(difference_in_time / (1000 * 3600 * 24));

    const startDate = range[0].startDate;
    const endDate = range[0].endDate;
    const monthOption = { month: 'short' };
    const dateOption = { day: 'numeric' };
    const dayOption = { weekday: "short" };
    const month = startDate.toLocaleDateString('en-US', monthOption);
    const startIndex = startDate.toLocaleDateString('en-US', dateOption);
    const endIndex = endDate.toLocaleDateString('en-US', dateOption);

    console.log(startDate)
    console.log(startDate)
    console.log(endDate)
    console.log(startIndex)
    console.log(endIndex)

    const datesArray = [];
    let currentDate = new Date(startDate);

    for(let i = +startIndex; i <= endIndex; i++) {
        let day = currentDate.toLocaleDateString('en-US', dayOption);

        datesArray.push({
            date: i,
            day: day
        })

        currentDate.setDate(currentDate.getDate() + 1);
    }
    console.log(datesArray);

    return (
        <table id='table'>
            <thead>
                <tr>
                    <th>Date</th>
                    {names.map((name, key) =>
                        <th id={key}>
                            {name}
                        </th>
                    )}
                </tr>
            </thead>
            <tbody>
                { }
                <tr>
                    {/* <td>{startMonthAndDate}</td> */}
                    <td></td>
                    {names.map((name, key) =>
                        <td>
                            <label>Open - 4:00 pm</label>
                            <input type="number" defaultValue="0" />
                            <label>4:00 pm - Close</label>
                            <input type="number" defaultValue="0" />
                        </td>
                    )}
                </tr>
                <tr>
                    <td>2</td>
                    <td>Jacob</td>
                    <td>Thornton</td>
                    <td>@fat</td>
                </tr>
            </tbody>
        </table>
    );
}

export default Table;
